<?php
$uid=me()['id'];$u=q('SELECT id,nome,cpf,email,telefone,papel FROM usuarios WHERE id=?',[$uid])->fetch();if(!$u){$_SESSION=[];go('login');}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=trim((string)($_POST['email']??''));$phone=trim((string)($_POST['telefone']??''));$pass=(string)($_POST['senha_atual']??'');$new=(string)($_POST['senha_nova']??'');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('E-mail inválido.','error');go('perfil');}if($new!==''){ $hash=q('SELECT senha_hash FROM usuarios WHERE id=?',[$uid])->fetchColumn();if(!password_verify($pass,$hash)||strlen($new)<10){flash('Senha atual incorreta ou nova senha com menos de 10 caracteres.','error');go('perfil');}q('UPDATE usuarios SET senha_hash=? WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$uid]);}try{q('UPDATE usuarios SET email=?,telefone=? WHERE id=?',[$email?:null,$phone?:null,$uid]);flash('Perfil atualizado.');}catch(PDOException $e){if($e->getCode()==='23000')flash('Este e-mail já está cadastrado.','error');else throw $e;}go('perfil');}
render_header('Meu perfil');?><div class="page-head"><div><div class="eyebrow">MINHA CONTA</div><h1>Meu perfil</h1><p>Atualize seus dados e mantenha seu acesso seguro.</p></div></div><section class="panel profile-panel"><div class="profile-banner"><div class="avatar"><?=h(mb_strtoupper(mb_substr($u['nome'],0,1)))?></div><div><h2><?=h($u['nome'])?></h2><p><?=h(ucfirst($u['papel']))?> · CPF final <?=h(substr($u['cpf'],-4))?></p></div></div><form method="post" class="stack"><?=csrf_field()?><label>E-mail<input type="email" name="email" value="<?=h($u['email'])?>"></label><label>Telefone<input type="tel" name="telefone" value="<?=h($u['telefone'])?>"></label><div class="divider-text">Alterar senha (opcional)</div><label>Senha atual<input type="password" name="senha_atual" autocomplete="current-password"></label><label>Nova senha<input type="password" name="senha_nova" minlength="10" autocomplete="new-password"></label><button class="btn btn-primary">Salvar alterações</button></form></section><?php render_footer();
